mapper.select:
SELECT * FROM message
WHERE status = 'approved' AND is_caught = 0
AND user_id != #{excludeUserId}
ORDER BY id LIMIT 1 OFFSET #{offset}

mapper.update:
UPDATE message
SET status = #{status}, review_reason = #{reason},
    heal_tag = #{healTag}, healing_message = #{healingMessage}
WHERE id = #{id}

UPDATE message
SET is_caught = 1, caught_by = #{userId}, caught_at = NOW()
WHERE id = #{id} AND is_caught = 0 AND user_id != #{userId}

mapper.select:
SELECT * FROM message

    status = #{status}

ORDER BY created_at DESC
